#### Expected Behavior
One-day historical data requests for forex behave like equity.

#### Actual Behavior
One-day historical data requests for forex does not return data on Monday.

#### Potential Solution
N/A

#### Reproducing the Problem
```csharp
namespace QuantConnect.Algorithm.CSharp {
    public class BasicTemplateAlgorithm : QCAlgorithm {
        private Symbol _symbol;
        private int _day = -1;
        
        public override void Initialize() {
            SetStartDate(2018, 1, 1); 
            SetEndDate(2019, 1, 1);
            _symbol = AddForex("EURUSD", Resolution.Minute).Symbol;
        }

        public override void OnData(Slice data) {

            if (Time.Day == _day) return;

            _day = Time.Day;
            var history = History(1, Resolution.Daily).Get<QuoteBar>(_symbol).ToList();

            if (!history.Any()) Debug($"No data on the eve of {Time} {Time.DayOfWeek}");
        }
    }
}
```
